package com.careerverse.servlet;
import com.careerverse.config.DB; import com.google.gson.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
@WebServlet("/app/api/assessment") public class AssessmentServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{JsonObject o=JsonParser.parseReader(r.getReader()).getAsJsonObject();int uid=(int)r.getSession().getAttribute("userId");try(Connection c=DB.getConnection();PreparedStatement q=c.prepareStatement("INSERT INTO assessments(user_id,logical_score,programming_score,communication_score,mathematics_score,creativity_score,analytical_score) VALUES(?,?,?,?,?,?,?)")){q.setInt(1,uid);q.setInt(2,o.get("logical").getAsInt());q.setInt(3,o.get("programming").getAsInt());q.setInt(4,o.get("communication").getAsInt());q.setInt(5,o.get("mathematics").getAsInt());q.setInt(6,o.get("creativity").getAsInt());q.setInt(7,o.get("analytical").getAsInt());q.executeUpdate();}s.setContentType("application/json");s.getWriter().print("{\"ok\":true}");}catch(Exception e){s.sendError(500,e.getMessage());}}}
